fn left(value: String) { println(value.as_str()) }
fn right(value: String) { println(value.as_str()) }
fn main() { left(String.from("L")) right(String.from("R")) }

fn repeat(value: String) { var i: Int32
i = 0
loop i < 2 { println(value.as_str()) i = i + 1 } }
fn main() { repeat(String.from("loop")) }
